// Real-time geometry. Warehouse layout is illustrative; traveler state comes from ReVolve.
let renderer,scene,camera,host,labels,frame=0,orbit=-.12,zoom=1,drag=null,pallets=new Map(),targets=[],selectedHalo;
const locations=[[-10,-3],[-2,-3],[6,-3],[8,3],[-5,5],[-12,5],[3,7]],names=['Receiving','Inspection','Testing','Disposition','Inventory','Shipping','Exception hold'];
const palette={steel:0x48545b,metal:0x8d999d,floor:0xbfc5c2,green:0x00866a,amber:0xe8a624,red:0xc74337,blue:0x2e6d89};
const materials=new Map();
function mat(color,roughness=.7){const k=color+':'+roughness;if(!materials.has(k))materials.set(k,new THREE.MeshStandardMaterial({color,roughness,metalness:roughness<.5?.45:.08}));return materials.get(k);}
function box(parent,x,y,z,w,h,d,color,roughness=.7){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat(color,roughness));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
