function line(points,color,width=1){const geo=new THREE.BufferGeometry().setFromPoints(points.map(p=>new THREE.Vector3(...p)));const l=new THREE.Line(geo,new THREE.LineBasicMaterial({color,linewidth:width}));scene.add(l);return l;}
function outline(x,z,w,d,color){line([[x-w/2,.025,z-d/2],[x+w/2,.025,z-d/2],[x+w/2,.025,z+d/2],[x-w/2,.025,z+d/2],[x-w/2,.025,z-d/2]],color);}
function server(parent,x,y,z,w=.7,h=1.2){box(parent,x,y+h/2,z,w,h,.65,0x41494c,.35);box(parent,x,y+h/2,z+.335,w*.87,h*.92,.035,0x20292c);for(let i=0;i<6;i++){box(parent,x,y+.14+i*h*.13,z+.36,w*.7,.018,.02,0x768184);box(parent,x+w*.32,y+.14+i*h*.13,z+.38,.025,.025,.02,i%3?0x38bf8b:0x83d5e0);}box(parent,x-w*.32,y+h/2,z+.37,.018,h*.8,.02,0xa3acad);}
function rack(x,z,rotation=0){const g=new THREE.Group();g.position.set(x,0,z);g.rotation.y=rotation;scene.add(g);for(const xx of [-1.6,1.6])for(const zz of [-.65,.65])box(g,xx,1.75,zz,.09,3.5,.09,0x536779);for(const y of [.18,1.35,2.5,3.45]){box(g,0,y,.7,3.3,.12,.08,0xe7982f);box(g,0,y,-.7,3.3,.12,.08,0xe7982f);box(g,0,y,0,3.2,.05,1.3,0x7e898a);if(y<3)for(let k=0;k<3;k++){box(g,-1.05+k*1.05,y+.35,0,.8,.65,1,0x929b96);box(g,-1.05+k*1.05,y+.35,.51,.58,.28,.012,0xe2e5df);}}return g;}
function monitor(parent,x,y,z){box(parent,x,y,z,.65,.42,.07,0x283237);box(parent,x,y,z+.045,.57,.33,.01,0x7cafc2);box(parent,x,y-.28,z,.05,.2,.05,0x636e72);box(parent,x,y-.4,z,.35,.03,.2,0x505b60);for(let i=0;i<3;i++)box(parent,x-.12,y+.07-i*.09,z+.057,.25+i*.03,.02,.005,0xd9eced);}
function bench(x,z,type){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);box(g,0,1.15,0,3.1,.15,1.3,0xb9c1be);for(const xx of [-1.35,1.35])for(const zz of [-.5,.5])box(g,xx,.55,zz,.09,1.1,.09,0x68787c);box(g,0,1.9,-.6,3,.08,.08,0x829394);for(const xx of [-1.4,1.4])box(g,xx,1.55,-.6,.07,1.1,.07,0x829394);monitor(g,-.65,1.8,-.25);server(g,.55,1.23,0,.6,.8);box(g,-.7,1.25,.35,.65,.025,.18,0x3f4e52);if(type==='testing'){for(let i=0;i<3;i++)server(g,-1+i*.9,0,1.8,.65,1.5);}return g;}
function worker(x,z,rotation=0){const g=new THREE.Group();g.position.set(x,0,z);g.rotation.y=rotation;scene.add(g);cylinder(g,0,1.65,0,.16,.32,0xb58865);box(g,0,1.18,0,.44,.6,.25,0xd7e439);box(g,0,1.17,.135,.055,.55,.025,0xe7eee8);box(g,0,1.12,.14,.42,.05,.025,0xdce7e2);for(const side of [-1,1]){box(g,side*.13,.55,0,.15,.65,.19,0x263d47);box(g,side*.13,.19,.08,.19,.12,.32,0x253338);const arm=box(g,side*.3,1.12,.08,.13,.55,.14,0x718a8e);arm.rotation.x=-.4;}return g;}
function truck(x,z,rotation){const g=new THREE.Group();g.position.set(x,0,z);g.rotation.y=rotation;scene.add(g);box(g,0,1.5,0,2.1,2.3,4.2,0xe4e8e5);box(g,0,.4,0,1.8,.3,5.5,0x344045);box(g,0,1,-2.9,2,1.5,1.5,0xd8e1df);box(g,0,1.35,-3.67,1.7,.6,.02,0x46646c);box(g,1.065,1.55,0,.015,.045,1.5,0x068667);box(g,1.065,1.75,-.73,.015,.42,.045,0x068667);box(g,1.065,1.75,.73,.015,.42,.045,0x068667);box(g,1.065,1.95,0,.015,.045,1.5,0x068667);for(const xx of [-1,1])for(const zz of [-2.7,1.5]){const wheel=cylinder(g,xx,.43,zz,.4,.25,0x283238);wheel.rotation.z=Math.PI/2;}return g;}
function fence(x,z,w,d){for(const xx of [-w/2,w/2])for(const zz of [-d/2,d/2])cylinder(scene,x+xx,.65,z+zz,.035,1.3,palette.red);for(const zz of [-d/2,d/2]){box(scene,x,.7,z+zz,w,.035,.035,palette.red);box(scene,x,1.27,z+zz,w,.035,.035,palette.red);for(let i=0;i<=w/.3;i++)box(scene,x-w/2+i*.3,.65,z+zz,.012,1.2,.012,0xb75750);}for(const xx of [-w/2,w/2]){box(scene,x+xx,.7,z,.035,.035,d,palette.red);for(let i=0;i<=d/.3;i++)box(scene,x+xx,.65,z-d/2+i*.3,.012,1.2,.012,0xb75750);}}
function floorTexture(){const c=document.createElement('canvas');c.width=c.height=256;const ctx=c.getContext('2d');ctx.fillStyle='#c9ceca';ctx.fillRect(0,0,256,256);let seed=3;for(let i=0;i<16000;i++){seed=(seed*16807)%2147483647;const v=185+seed%45;ctx.fillStyle=`rgba(${v},${v},${v},.12)`;ctx.fillRect(seed%256,(seed>>8)%256,2,2);}ctx.strokeStyle='#aab5af';ctx.lineWidth=1;ctx.strokeRect(0,0,256,256);const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(12,8);t.colorSpace=THREE.SRGBColorSpace;return t;}
function build(){scene=new THREE.Scene();scene.background=new THREE.Color(0xdde6e1);scene.fog=new THREE.Fog(0xdde6e1,50,100);camera=new THREE.PerspectiveCamera(37,1,.1,120);
 scene.add(new THREE.HemisphereLight(0xf6fbff,0x87918b,2.4));const sun=new THREE.DirectionalLight(0xfff5de,3.2);sun.position.set(-12,25,12);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-23,right:23,top:23,bottom:-23,near:1,far:65});sun.shadow.normalBias=.04;scene.add(sun);
 const floor=new THREE.Mesh(new THREE.BoxGeometry(34,.25,24),new THREE.MeshStandardMaterial({map:floorTexture(),roughness:.88}));floor.position.y=-.15;floor.receiveShadow=true;scene.add(floor);
 box(scene,0,2.6,-11.7,34,5.2,.22,0xc9d3cf);box(scene,-16.7,2.6,0,.22,5.2,24,0xc2ceca);box(scene,0,1.5,-11.55,34,.16,.03,palette.green);
 for(let x=-16;x<=16;x+=4){box(scene,x,2.7,-11.45,.15,5.4,.2,0x83918e);box(scene,x,4.2,-11.5,2.7,.65,.04,0xb2c8cd);}for(let z=-10;z<=10;z+=4)box(scene,-16.5,2.7,z,.2,5.4,.15,0x82908c);
 for(const z of [-5,5]){box(scene,-16.45,1.6,z,.12,3.2,3.2,0x566971);for(let y=.3;y<3.2;y+=.25)box(scene,-16.36,y,z,.02,.025,3.1,0x91a19f);for(const zz of [z-1.9,z+1.9]){cylinder(scene,-15.9,.55,zz,.08,1.1,palette.amber);}}
 [-11,-7,-3,1,5,9,13].forEach(x=>rack(x,-8.2));rack(-9,7.5);rack(-5,7.5);
 locations.slice(0,6).forEach(([x,z],i)=>outline(x,z,5.6,4.4,palette.amber));outline(3,7,5,3.5,palette.red);fence(3,7,5,3.5);
 bench(-2,-4,'inspection');bench(6,-4,'testing');bench(9,2,'disposition');worker(-2,-2.8);worker(6,-2.8);worker(9,3.2);worker(-10,-3,Math.PI/2);worker(-10,4,Math.PI/2);
 truck(-13,-6,Math.PI/2);truck(-13,8,Math.PI/2);
 const route=[[-10,.04,-.5],[-2,.04,-.5],[6,.04,-.5],[9,.04,.8],[7,.04,4.8],[-2,.04,4.8],[-10,.04,4.8]];const path=new THREE.Line(new THREE.BufferGeometry().setFromPoints(route.map(p=>new THREE.Vector3(...p))),new THREE.LineDashedMaterial({color:0x019f76,dashSize:.45,gapSize:.3}));path.computeLineDistances();scene.add(path);
 for(const [x,z] of [[-7,-.5],[2,-.5],[4,4.8],[-7,4.8]]){const arrow=new THREE.Mesh(new THREE.ConeGeometry(.15,.45,3),mat(0x01a982));arrow.rotation.z=-Math.PI/2;arrow.position.set(x,.08,z);arrow.rotation.x=Math.PI/2;scene.add(arrow);}
 const ring=new THREE.Mesh(new THREE.RingGeometry(.65,.75,40),new THREE.MeshBasicMaterial({color:0x10e4be,side:THREE.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.y=.03;scene.add(ring);selectedHalo=ring;
}
function createPallet(id,state){const g=new THREE.Group();box(g,0,.08,0,1.05,.14,.95,0xa18d62);for(const x of [-.4,0,.4])box(g,x,.03,0,.12,.08,.9,0x756649);server(g,0,.17,0,.72,1.05);const base=box(g,0,.17,0,1.1,.035,1,state==='blocked'?palette.red:state==='queued'?palette.amber:palette.green);g.userData={id,base};g.traverse(o=>{o.userData.id=id;});scene.add(g);pallets.set(id,g);return g;}
function send(type,value){window.dispatchEvent(new CustomEvent(type,{detail:value}));}
function update(){if(!scene)return;const data=window.TwinSceneData;if(!data)return;const ids=new Set(data.tokens.map(t=>t.id));for(const [id,g] of pallets)if(!ids.has(id)){scene.remove(g);g.traverse(o=>{if(o.isMesh)o.geometry.dispose();});pallets.delete(id);}for(const t of data.tokens){const [x,z]=locations[t.s];const g=pallets.get(t.id)||createPallet(t.id,t.state);g.userData.target=new THREE.Vector3(x-1.6+(t.n%5)*.83,0,z+.3+Math.floor(t.n/5)*.95);if(!g.userData.placed){g.position.copy(g.userData.target);g.userData.placed=true;}g.userData.base.material=mat(t.state==='blocked'?palette.red:t.state==='queued'?palette.amber:palette.green);}const chosen=pallets.get(data.selected);selectedHalo.visible=!!chosen;if(chosen)selectedHalo.position.set(chosen.position.x,.03,chosen.position.z);}
function cameraPosition(){camera.position.set(Math.sin(orbit+.65)*36/zoom,28/zoom,Math.cos(orbit+.65)*36/zoom);camera.lookAt(0,0,0);}
function mount(){const next=document.querySelector('.twin-viewport');if(!next)return;if(host===next)return;host=next;host.classList.add('webgl-ready');
 try{if(!renderer){renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;build();}host.append(renderer.domElement);renderer.domElement.setAttribute('aria-label','3D warehouse. Drag to rotate, scroll to zoom. Use station labels and return buttons for keyboard access.');renderer.domElement.setAttribute('role','img');labels=document.createElement('div');labels.className='warehouse-labels';host.append(labels);names.forEach((name,i)=>{const b=document.createElement('button');b.className='warehouse-label'+(i===6?' hold-label':'');b.textContent=name;b.onclick=()=>send('twin-station-pick',i);b.dataset.station3d=i;labels.append(b);});const selected=document.createElement('div');selected.className='warehouse-selection';labels.append(selected);
 renderer.domElement.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,moved:false};renderer.domElement.setPointerCapture(e.pointerId);};renderer.domElement.onpointermove=e=>{if(drag){if(Math.abs(e.clientX-drag.x)>2)drag.moved=true;orbit-=(e.clientX-drag.x)*.008;drag.x=e.clientX;drag.y=e.clientY;}};renderer.domElement.onpointerup=e=>{if(drag&&!drag.moved){const rect=renderer.domElement.getBoundingClientRect(),ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1),camera);const hits=ray.intersectObjects([...pallets.values()],true);if(hits[0]?.object.userData.id)send('twin-pallet-pick',hits[0].object.userData.id);}drag=null;};renderer.domElement.onpointercancel=()=>drag=null;renderer.domElement.onwheel=e=>{e.preventDefault();zoom=THREE.MathUtils.clamp(zoom-e.deltaY*.0007,.65,1.65);};update();resize();if(!frame)animate();
 }catch(e){host.classList.remove('webgl-ready');const n=document.createElement('p');n.className='warehouse-fallback';n.textContent='WebGL unavailable. Showing the simplified 3D view; travelers and simulation remain available.';host.append(n);console.error(e);}}
function resize(){if(!renderer||!host?.isConnected)return;const w=host.clientWidth,h=host.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();}
function project(x,y,z){const v=new THREE.Vector3(x,y,z).project(camera);return [(v.x*.5+.5)*host.clientWidth,(-v.y*.5+.5)*host.clientHeight];}
function animate(){frame=requestAnimationFrame(animate);if(!host?.isConnected)return;cameraPosition();for(const g of pallets.values())if(g.userData.target)g.position.lerp(g.userData.target,.12);const data=window.TwinSceneData;for(let i=0;i<7;i++){const [x,z]=locations[i],p=project(x,3,z-1.4),el=labels.querySelector(`[data-station3d="${i}"]`);el.style.left=p[0]+'px';el.style.top=p[1]+'px';}const g=pallets.get(data?.selected),el=labels.querySelector('.warehouse-selection');el.hidden=!g;if(g){const p=project(g.position.x,1.9,g.position.z);el.style.left=p[0]+'px';el.style.top=p[1]+'px';el.textContent=data.selected+(g.userData.base.material.color.getHex()===palette.red?' · On hold':'');selectedHalo.position.set(g.position.x,.035,g.position.z);}renderer.render(scene,camera);}
window.addEventListener('resize',resize);window.addEventListener('twin-scene-update',()=>{mount();update();});window.addEventListener('twin-camera',e=>{if(e.detail==='left')orbit-=.2;if(e.detail==='right')orbit+=.2;if(e.detail==='zoom')zoom=zoom===1?1.3:1;if(e.detail==='reset'){orbit=-.12;zoom=1;}cameraPosition();});window.addEventListener('hashchange',()=>setTimeout(mount,0));mount();
